y:grid;gap:8px}.character-pick{background:#fff;border:1px solid #eeeaf2;border-radius:13px;padding:10px;display:flex;align-items:center;gap:10px;text-align:left;cursor:pointer;transition:.18s}.character-pick:hover{border-color:#d6c9ef;transform:translateY(-1px)}.character-pick.active{background:#f8f5ff;border-color:#cfc0ef;box-shadow:0 0 0 2px #ede6fc}.pick-copy{display:grid;gap:3px;flex:1}.pick-copy strong{font:700 12px Manrope}.pick-copy small{font-size:9.5px;color:#9991a1}.pick-check{display:none;width:17px;height:17px;align-items:center;justify-content:center;background:#8066c5;color:#fff;border-radius:50%;font-size:10px}.character-pick.active .pick-check{display:flex}.pick-avatar,.profile-avatar{position:relative;display:grid;place-items:center;flex:none;overflow:hidden;border-radius:11px;background:linear-gradient(145deg,#ffe1cf,#f7c9bd);width:38px;height:38px}.pick-avatar .mini-hair,.profile-avatar .mini-hair{position:absolute;top:3px;left:8px;width:24px;height:17px;border-radius:12px 12px 7px 7px;background:#604351}.pick-avatar .mini-face,.profile-avatar .mini-face{position:absolute;color:#e5a984;font-size:28px;line-height:1;top:7px;left:9px;text-shadow:0 5px 0 #f3be9c}.mira-mini{background:linear-gradient(145deg,#fbdacb,#f0bba6)}.leo-mini{background:linear-gradient(145deg,#d9e8e8,#a6c4be)}.leo-mini .mini-hair{background:#473b39;width:23px;border-radius:10px 11px 6px 6px}.leo-mini .mini-face{color:#b9785f;text-shadow:0 5px 0 #d29372}.side-rule{height:1px;background:var(--line);margin:22px 0 19px}.mood-label{margin-bottom:11px}.mood-options{display:grid;grid-template-columns:1fr 1fr;gap:7px}.mood-chip{border:1px solid #eeeaf2;background:#fff;border-radius:10px;padding:9px 8px;display:flex;align-items:center;gap:7px;font-size:11px;color:#777082;cursor:pointer;transition:.15s}.mood-chip:nth-child(3){grid-column:span 2}.mood-chip.selected{background:#f6f2ff;border-color:#d2c4f1;color:#6e56b4}.boundaries-card{display:flex;gap:10px;background:#fbf9fd;border:1px so