ransform-origin:bottom center;transition:transform .35s ease;filter:drop-shadow(0 11px 10px #99756c2e)}.head{position:absolute;z-index:4;top:8px;left:42px;width:77px;height:91px;border-radius:44% 47% 47% 46%;background:#f1bd9b;box-shadow:inset -7px -1px #e6a988}.ear{position:absolute;top:39px;width:15px;height:21px;border-radius:50%;background:#e9ae8b;z-index:-1}.ear-left{left:-8px}.ear-right{right:-8px}.hair-back{position:absolute;z-index:-1;top:-7px;left:-4px;width:84px;height:107px;border-radius:50% 48% 37% 42%;background:#694456}.face{position:absolute;inset:0;z-index:1}.eye{position:absolute;top:44px;width:5px;height:7px;background:#45333a;border-radius:50%;transition:.2s}.eye-left{left:20px}.eye-right{right:19px}.brow{position:absolute;top:36px;width:13px;height:3px;border-radius:50%;background:#79534a;transform:rotate(-7deg)}.brow-left{left:16px}.brow-right{right:15px;transform:rotate(7deg)}.nose{position:absolute;left:36px;top:52px;width:5px;height:8px;border-right:1px solid #d09177;border-bottom:1px solid #d09177;border-radius:0 0 6px}.mouth{position:absolute;left:31px;top:67px;width:15px;height:6px;border-bottom:2px solid #ac5e68;border-radius:50%}.cheek{position:absolute;top:59px;width:13px;height:6px;background:#e98e8e55;filter:blur(3px);border-radius:50%}.cheek-left{left:5px}.cheek-right{right:4px}.hair-front{position:absolute;z-index:2;top:-7px;left:0;width:83px;height:40px}.hair-piece{position:absolute;top:1px;left:1px;width:38px;height:34px;background:#694456;border-radius:65% 20% 65% 20%;transform:rotate(4deg)}.hair-piece.two{left:25px;top:-4px;width:37px;height:40px;border-radius:80% 30% 45% 28%;transform:rotate(24deg);background:#744a5d}.hair-piece.three{left:51px;top:5px;width:31px;height:36px;border-radius:20% 80% 30% 80%;transform:rotate(-12deg)}.neck{position:absolute;top:86px;left:70px;width:25px;height:32px;background:#e7ad8a;z-index:2}.body{position:absolute;z-index:3;top:103px;left:18px;width:121px;height:155px;border-radius:39px 39px 15px 15px;background:linear-gradient(110deg,#8b79bd,#7765aa);box-shadow:inset -12px 0 #665796}.shirt-detail{position:absolute;top:1px;left:46px;width:25px;height:30px;background:#f1bd9b;clip-path:polygon(0 0,100% 0,51% 100%)}.shirt-pocket{position:absolute;right:18px;top:55px;width:20px;height:25px;border:1px solid #ffffff44;border-top:0;border-radius:0 0 5px 5px}.legs{position:absolute;z-index:2;top:236px;left:30px;width:98px;height:70px}.leg{position:absolute;top:0;width:44px;height:70px;background:#665d79;border-radius:0 0 14px 14px}.leg-left{left:5px;transform:rotate(3deg)}.leg-right{right:4px;transform:rotate(-3deg)}.leg::after{content:'';position:absolute;bottom:-5px;left:-5px;width:52px;height:16px;border-radius:10px 16px 7px 7px;background:#f5eee8}.arm{position:absolute;z-index:2;top:119px;width:35px;height:103px;border-radius:22px;background:#f0bb98;transform-origin:top center;transition:transform .35s ease}.arm-left{left:12px;transform:rotate(12deg)}.arm-right{right:9px;transform:rotate(-12deg)}.hand{position:absolute;bottom:-4px;left:3px;width:27px;height:29px;border-radius:45% 45% 50% 50%;background:#efb690}.pose-bubble{position:absolute;bottom:57%;left:calc(50% + 91px);white-space:nowrap;background:#fff;color:#746b7c;padding:8px 11px;border-radius:12px;font-size:9px;box-shadow:0 4px 15px #715c7618;animation:floaty 3s ease-in-out infinite}.pose-bubble::after{content:'';position:absolute;left:10px;bottom:-5px;border-width:5px 5px 0 0;border-style:solid;border-color:white transparent transparent transparent}.ambient-spark{position:absolute;color:#fff9db;font-size:20px;z-index:3;text-shadow:0 1px 6px #fff}.ambient-one{top:44%;left:17%;animation:twinkle 2s infinite}.ambient-two{top:29%;right:17%;font-size:16px;animation:twinkle 2.5s .5s infinite}.ambient-three{top:58%;right:28%;font-size:34px;opacity:.8}.scene-footer{min-height:91px;display:flex;align-items:center;justify-content:space-between;gap:10px}.connection{display:flex;align-items:center;gap:10px;min-width:120px}.heart-pulse{width:33px;height:33px;display:grid;place-items:center;border-radius:11px;background:#fff1f0;color:#e1908b;font-size:15px;animation:heart 2s ease-in-out infinite}.connection div{display:grid;gap:4px}.connection strong{font:700 10px Manrope}.connection small{font-size:9px;color:#a29aa8}.action-bar{display:flex;gap:6px}.action-button{background:#fbf9fd;border:1px solid #eeeaf2;padding:8px 10px;border-radius:10px;font-size:10px;color:#777082;cursor:pointer;transition:.16s;white-space:nowrap}.action-button span{font-size:13px;margin-right:3px}.action-button:hover{background:#f5f0ff;border-color:#d9cdf0;transform:translateY(-2px)}.chat-panel{display:flex;flex-direction:column;min-height:0;overflow:hidden}.chat-header{height:68px;flex:none;padding:0 16px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #f0edf3}.chat-profile{display:flex;align-items:center;gap:10px}.profile-avatar{width:38px;height:38px;border-radius:12px}.profile-avatar .mini-hair{top:3px;left:8px}.profile-avatar .mini-face{top:7px;left:9px}.online-dot{position:absolute;right:2px;bottom:2px;width:9px;height:9px;background:#83b79b;border:2px solid white;border-radius:50%}.chat-profile div{display:grid;gap:4px}.chat-profile strong{font:700 12px Manrope}.chat-profile small{font-size:9.5px;color:#a19aa7;display:flex;align-items:center;gap:5px}.typing-indicator{display:inline-flex;gap:2px}.typing-indicator i{width:3px;height:3px;background:#84b198;border-radius:50%;animation:typing 1s infinite}.typing-indicator i:nth-child(2){animation-delay:.15s}.typing-indicator i:nth-child(3){animation-delay:.3s}.chat-menu{border:0;background:none;color:#aaa2af;font-weight:700;font-size:19px;letter-spacing:2px;cursor:pointer}.chat-log{padding:17px 14px 8px;display:flex;flex-direction:column;gap:14px;overflow-y:auto;flex:1;scrollbar-width:thin;scrollbar-color:#e3dceb transparent}.message{max-width:88%;display:flex;flex-direction:column;gap:4px;animation:message-in .24s ease-out}.message.companion{align-self:flex-start}.message.player{align-self:flex-end;align-items:flex-end}.message .bubble{padding:10px 12px;border-radius:4px 14px 14px 14px;background:#f5f2f8;color:#5e5765;line-height:1.5;font-size:11px;overflow-wrap:anywhere}.message.player .bubble{background:#8069bf;color:#fff;border-radius:14px 4px 14px 14px}.message .stamp{font-size:8px;color:#b1aab5;padding:0 3px}.chat-prompts{display:flex;gap:6px;overflow-x:auto;padding:8px 13px 10px;scrollbar-width:none}.chat-prompts::-webkit-scrollbar{display:none}.prompt-chip{border:1px solid #e8e0f2;background:#fff;border-radius:20px;padding:7px 10px;font-size:9px;color:#7765a8;white-space:nowrap;cursor:pointer}.prompt-chip:hover{background:#f7f3ff}.composer{margin:0 12px 10px;border:1px solid #eae5ef;border-radius:13px;display:flex;align-items:center;padding:4px;background:#fff;transition:.2s}.composer:focus-within{border-color:#cdbfea;box-shadow:0 0 0 3px #f3effa}.composer input{border:0;outline:0;min-width:0;flex:1;padding:9px;font-size:11px;color:var(--ink);background:transparent}.composer input::placeholder{color:#b1aab5}.composer button{border:0;border-radius:10px;width:34px;height:32px;background:#8069bf;color:#fff;font-size:19px;line-height:1;cursor:pointer;transition:.15s}.composer button:hover{background:#6f56ad;transform:translateY(-1px)}.chat-footnote{font-size:8px;text-align:center;color:#b2abb5;padding:0 8px 13px}.chat-footnote span{margin:0 4px;color:#d4a19a}.page-footer{height:44px;display:flex;align-items:center;justify-content:space-between;color:#aaa2b0;font-size:8px;font-weight:700;letter-spacing:1.2px}.page-footer span:last-child{color:#9e90ba}.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#383143;color:white;border-radius:12px;padding:11px 16px;font-size:11px;box-shadow:0 8px 25px #34283b33;transition:.25s;z-index:30}.toast.visible{opacity:1;transform:translate(-50%,0)}.about-dialog{border:1px solid #eee8f3;border-radius:20px;padding:30px;max-width:390px;color:var(--ink);box-shadow:0 20px 70px #31263b40;text-align:center}.about-dialog::backdrop{background:#332c3d66;backdrop-filter:blur(3px)}.dialog-close{position:absolute;right:15px;top:12px;background:none;border:0;color:#9d94a4;font-size:23px;cursor:pointer}.dialog-sparkle{display:inline-grid;place-items:center;width:42px;height:42px;border-radius:14px;background:#f1ebfd;color:#8069bf;font-size:24px}.about-dialog h2{font:800 20px Manrope;margin:13px 0 8px}.about-dialog p{font-size:12px;line-height:1.7;color:#817987}.dialog-ok{background:#8069bf;color:white;border:0;border-radius:11px;padding:10px 20px;cursor:pointer;margin-top:8px}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
