#person.leo .hair-back,#person.leo .hair-piece,#person.leo .hair-piece.two,#person.leo .hair-piece.three{background:#493b39}#person.leo .hair-back{height:83px;border-radius:49% 49% 24% 24%}#person.leo .hair-piece{height:23px;top:0;border-radius:60% 40% 30% 20%}#person.leo .hair-piece.two{height:27px;top:-2px}#person.leo .hair-piece.three{height:23px;top:2px}#person.leo .body{background:linear-gradient(110deg,#68988f,#53847d);box-shadow:inset -12px 0 #47736f}#person.leo .legs .leg{background:#5b626f}#person.leo .neck,#person.leo .head{background:#bd8064}#person.leo .head{box-shadow:inset -7px -1px #ae7059}#person.leo .ear{background:#b9785f}#person.leo .arm,#person.leo .hand{background:#bd8064}#character-stage[data-pose="wave"] .arm-right{transform:rotate(-150deg)}#character-stage[data-pose="wave"] .hand{transform:rotate(20deg)}#character-stage[data-pose="dance"] .person{animation:dance .55s ease-in-out 4}#character-stage[data-pose="dance"] .arm-left{transform:rotate(125deg)}#character-stage[data-pose="dance"] .arm-right{transform:rotate(-140deg)}#character-stage[data-pose="laugh"] .head{transform:rotate(-8deg)}#character-stage[data-pose="laugh"] .mouth{height:11px;border:0;background:#a85464;border-radius:4px 4px 10px 10px}#character-stage[data-pose="laugh"] .eye{height:2px;transform:rotate(-9deg)}#character-stage[data-pose="breathe"] .person{animation:breathe 3s ease-in-out 2}#character-stage[data-pose="breathe"] .eye{height:2px}#character-stage[data-pose="think"] .arm-right{transform:rotate(-60deg)}#character-stage[data-pose="think"] .hand{top:-3px}#character-stage[data-pose="sit"] .person{transform:translateY(25px) scale(.93)}#character-stage[data-pose="sit"] .legs{transform:rotate(22deg);transform-origin:top center}#character-stage[data-pose="cheer"] .arm-left{transform:rotate(145deg)}#character-stage[data-pose="cheer"] .arm-right{transform:rotate(-145deg)}#character-stage[data-pose="blush"] .cheek{background:#e878786e;filter:blur(4px);width:18px;height:10px}#scene-backdrop.scene-evening{background:linear-gradient(180deg,#c8c0df,#e6bed0 62%,#d19e9c)}#scene-backdrop.scene-evening .window{background:linear-gradient(180deg,#9290c4,#efb9a6)}#scene-backdrop.scene-beach{background:linear-gradient(180deg,#a9d8e2,#f4d8c0 65%,#edd0a7)}#scene-backdrop.scene-beach .window{background:linear-gradient(180deg,#9ed4e4,#ffe5b4)}#scene-backdrop.scene-garden{background:linear-gradient(180deg,#c8e0cf,#f2e7c9 65%,#d7c49c)}#scene-backdrop.scene-garden .window{background:linear-gradient(180deg,#9fc9b5,#f6dfb4)}
